SELECT T1.ENTRUST_ID entrustId, T1.ENTRUST_STATUS entrustStatus, T7.REAL_NAME invManagerId, T1.PORTFOLIO_ID portfolioId, T2.PORTFOLIO_NAME portfolioName, T5.FINPROD_MARKET_ID finprodId, T4.TARGET_FINPROD_ID targetFinprodId, NVL( T5.FINPROD_ABBR,T5.FINPROD_NAME) targetFinprodName, T3.BUSI_PS busiPs, T1.TRADE_MARKET tradeMarket, T1.ENTRUST_AMT totalAmt, T1.CCY ccy, T1.VDATE vdate, T1.MDATE mdate, NVL(T6.FINISH_AMT,0) finishAmt, NVL2(T6.FINISH_AMT ,case when T1.ENTRUST_AMT!=0 then ROUND(NVL(T6.FINISH_AMT,0)*100/(T1.ENTRUST_AMT*100),4) else 0 end,0) transactioncom, T1.REMARK remark, '' nextUser FROM ETR_ENTRUST T1 LEFT JOIN PTL_PORTFOLIO T2 ON T1.PORTFOLIO_ID = T2.PORTFOLIO_ID INNER JOIN ETR_ENTRUST_ADD T3 ON T1.ENTRUST_ID = T3.ENTRUST_ID INNER JOIN ETR_TARGET T4 ON T1.ENTRUST_ID = T4.ENTRUST_ID INNER JOIN FIN_PRODUCT T5 ON T4.TARGET_FINPROD_ID = T5.FINPROD_ID LEFT JOIN ( SELECT ENTRUST_ID, SUM(FINISH_AMT) AS FINISH_AMT FROM ETR_FINISH_STATUS GROUP BY ENTRUST_ID) T6 ON T1.ENTRUST_ID = T6.ENTRUST_ID LEFT JOIN SYS_USER T7 ON T1.INV_MANAGER_ID = T7.USER_NAME
AND T1.TRADE_MARKET = #{TRADE_MARKET_01} AND T1.FINPROD_TYPE2 IN
#{bond,jdbcType=VARCHAR}
AND (T2.PORTFOLIO_ID IN
null) OR T2.PORTFOLIO_ID IN (
#{prot}
or T2.PARENT_PORTFOLIO_ID IN
null) OR T2.PARENT_PORTFOLIO_ID IN (
#{prot}
)
AND (T4.TARGET_FINPROD_ID IN
null) OR T4.TARGET_FINPROD_ID IN (
#{prot,jdbcType=VARCHAR}
)
AND T1.CCY IN
#{prot}
AND T1.TRADE_MARKET IN
#{prot,jdbcType=VARCHAR}
AND T3.BUSI_PS = #{busiPs,jdbcType=VARCHAR}
AND T1.ENTRUST_STATUS IN
#{prot,jdbcType=VARCHAR}
AND T1.VDATE >=to_date(#{startDate},'yyyy-MM-dd')
AND T1.MDATE <=to_date(#{endDate},'yyyy-MM-dd')

SELECT T1.ENTRUST_ID entrustId, '08' entrustStatus, T7.REAL_NAME invManagerId, T1.PORTFOLIO_ID portfolioId, T2.PORTFOLIO_NAME portfolioName, T5.FINPROD_MARKET_ID finprodId, T4.TARGET_FINPROD_ID targetFinprodId, NVL( T5.FINPROD_ABBR,T5.FINPROD_NAME) targetFinprodName, T3.BUSI_PS busiPs, T1.TRADE_MARKET tradeMarket, T1.ENTRUST_AMT totalAmt, T1.CCY ccy, T1.VDATE vdate, T1.MDATE mdate, NVL(T6.FINISH_AMT,0) finishAmt, NVL2(T6.FINISH_AMT ,case when T1.ENTRUST_AMT!=0 then ROUND(NVL(T6.FINISH_AMT,0)*100/(T1.ENTRUST_AMT*100),4) else 0 end,0) transactioncom, T1.REMARK remark, SWBL.NEXT_USER nextUser FROM WFL_ETR_ENTRUST T1 LEFT JOIN PTL_PORTFOLIO T2 ON T1.PORTFOLIO_ID = T2.PORTFOLIO_ID INNER JOIN WFL_ETR_ENTRUST_ADD T3 ON T1.ENTRUST_ID = T3.ENTRUST_ID INNER JOIN WFL_ETR_TARGET T4 ON T1.ENTRUST_ID = T4.ENTRUST_ID INNER JOIN FIN_PRODUCT T5 ON T4.TARGET_FINPROD_ID = T5.FINPROD_ID LEFT JOIN ( SELECT ENTRUST_ID, SUM(FINISH_AMT) AS FINISH_AMT FROM ETR_FINISH_STATUS GROUP BY ENTRUST_ID) T6 ON T1.ENTRUST_ID = T6.ENTRUST_ID LEFT JOIN SYS_USER T7 ON T1.INV_MANAGER_ID = T7.USER_NAME LEFT JOIN SYS_WFL_BUSINESS_LIST SWBL ON SWBL.SEQ_NO = T1.WORKFLOW_ID
AND SWBL.PROCESS_STATE != 'END' AND T1.TRADE_MARKET = #{TRADE_MARKET_01} AND T1.FINPROD_TYPE2 IN
#{bond,jdbcType=VARCHAR}
AND (T2.PORTFOLIO_ID IN
null) OR T2.PORTFOLIO_ID IN (
#{prot}
or T2.PARENT_PORTFOLIO_ID IN
null) OR T2.PARENT_PORTFOLIO_ID IN (
