#{prot}
AND T1.TRADE_MARKET IN
#{prot,jdbcType=VARCHAR}
AND T3.BUSI_PS = #{busiPs,jdbcType=VARCHAR}
AND T1.VDATE >=to_date(#{startDate},'yyyy-MM-dd')
AND T1.MDATE <=to_date(#{endDate},'yyyy-MM-dd')

mapper.select:
SELECT A.FINPROD_ID id, A.FINPROD_MARKET_ID text, A.FINPROD_ID, A.FINPROD_NAME, TO_CHAR(A.VDATE, 'yyyy-MM-dd') VDATE, TO_CHAR(A.MDATE, 'yyyy-MM-dd') MDATE, TO_CHAR(A.IDATE, 'yyyy-MM-dd') IDATE, A.TRADE_MARKET, A.CCY, A.CALENDAR_ID, basisData.BASIS, B.TYPE_4 windtypeone, A.FINPROD_MARKET_ID, A.IS_RIGHT FROM FIN_PRODUCT A LEFT JOIN FIN_PRODUCT_ADD FPA ON FPA.FINPROD_ID = A.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE B ON B.FINPROD_ID = A.FINPROD_ID LEFT JOIN ( select max(BASIS) as BASIS, FINPROD_ID from FIN_CASH_CALC_RULE
AND FINPROD_ID = #{initValue}
group by FINPROD_ID ) basisData on A.FINPROD_ID = basisData.FINPROD_ID
( A.FINPROD_MARKET_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) or A.FINPROD_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )
AND A.FINPROD_ID = #{initValue}
AND A.FINPROD_TYPE2 = #{FINPROD_TYPE_TG}
AND B.TYPE_4 = #{windtypeone}
AND A.TRADE_MARKET = #{FINPROD_MARKET}
AND (FPA.IS_ISSUE_ASSET = 'N' OR FPA.IS_ISSUE_ASSET IS NULL)
union select interf.SECID id, interf.SECID text, fin.FINPROD_ID, interf.SECNAME FINPROD_NAME, null, null, null, null, null, null, null, null, null, null from interf_payhsrcsecinfo interf left join fin_product fin on interf.SECID = fin.FINPROD_ID where SECID not in (select FINPROD_MARKET_ID from fin_product A LEFT JOIN FIN_PRODUCT_TYPE B ON B.FINPROD_ID = A.FINPROD_ID
AND A.FINPROD_TYPE2 = #{FINPROD_TYPE_TG}
AND B.TYPE_4 = #{windtypeone}
)
AND interf.SECID = #{initValue}
and ( interf.SECID LIKE CONCAT('%', CONCAT(#{search}, '%')) or interf.SECNAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )
AND interf.MARKET = #{FINPROD_WIND_MARKET}

SELECT distinct A.ACCT_NO hidCode, A.ACCT_NO code, B.SEC_ACCT_NAME name, B.SEC_ACCT_NAME shortName FROM PTL_SEC_ACCT A INNER JOIN STL_SEC_ACCT_INFO B ON A.ACCT_NO = B.SEC_ACCT_ID
LEFT JOIN FIN_PRODUCT FP ON FP.FINPROD_ID =#{finprodId,jdbcType=VARCHAR}
PORTFOLIO_ID = #{portfolioId}
AND ( A.ACCT_NO LIKE CONCAT('%', CONCAT(#{search}, '%')) OR B.SEC_ACCT_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )
AND A.ACCT_NO = #{initValue}
AND FP.REGIST_ORG = B.REGIST_ORG
AND TRADE_PLACE = #{tradeMarket, jdbcType=VARCHAR}

SELECT T1.PORTFOLIO_ID portfolioId, T1.ENTRUST_ID entrustId, T1.VDATE vdate, T1.MDATE mdate, T1.AVAILABLE_NUM objectAvailablePosition, T1.FINPROD_ID finprodId, T1.ENTRUST_AMT totalAmt, T3.SEC_ACCT_ID secAcctId, T3.TERM_TYPE termType, T3.SETTLE_SPREED settleSpeed, T1.TRADE_MARKET tradeMarket, CASE T1.FINPROD_TYPE2 WHEN 'F29' THEN '05' WHEN 'F30' THEN '06' END busiPs, T1.CALENDAR_ID calendarId, T1.PRICE busiRate, T1.CCY ccy, T1.REMARK remark, T1.COUNTER_ID counterId, T1.COUNTER_TRADER counterTrader, T1.CONTACT_INFO contactInfo, T2.TRADER trader, T1.INV_MANAGER_ID invManagerId FROM ETR_ENTRUST T1 LEFT JOIN ETR_DISTRIBUTE T2 ON T1.ENTRUST_ID = T2.ENTRUST_ID INNER JOIN ETR_ENTRUST_ADD T3 ON T1.ENTRUST_ID = T3.ENTRUST_ID INNER JOIN FIN_PRODUCT T5 ON T1.FINPROD_ID = T5.FINPROD_ID
T1.PORTFOLIO_ID=#{portfolioId}
AND T1.FINPROD_ID = #{finprodId}
AND T1.ENTRUST_ID = #{entrustId}

SELECT T1.PORTFOLIO_ID portfolioId, T1.ENTRUST_ID entrustId, T1.VDATE vdate, T1.MDATE mdate, T1.AVAILABLE_NUM objectAvailablePosition, T1.FINPROD_ID finprodId, T1.ENTRUST_AMT totalAmt, T3.SEC_ACCT_ID secAcctId, T3.TERM_TYPE termType, T3.SETTLE_SPREED settleSpeed, T1.TRADE_MARKET tradeMarket, CASE T1.FINPROD_TYPE2 WHEN 'F29' THEN '05' WHEN 'F30' THEN '06' END busiPs, T1.CALENDAR_ID calendarId, T1.PRICE busiRate, T1.CCY ccy, T1.REMARK remark, T1.COUNTER_ID counterId, T1.COUNTER_TRADER counterTrader, T1.CONTACT_INFO contactInfo, T2.TRADER trader, T1.INV_MANAGER_ID invManagerId FROM WFL_ETR_ENTRUST T1 LEFT JOIN ETR_DISTRIBUTE T2 ON T1.ENTRUST_ID = T2.ENTRUST_ID INNER JOIN WFL_ETR_ENTRUST_ADD T3 ON T1.ENTRUST_ID = T3.ENTRUST_ID INNER JOIN FIN_PRODUCT T5 ON T1.FINPROD_ID = T5.FINPROD_ID
T1.PORTFOLIO_ID=#{portfolioId}
AND T1.FINPROD_ID = #{finprodId}
AND T1.ENTRUST_ID = #{entrustId}

select
SUM(AMOUNT)
from ETR_SEC_POSITION_RULE
where CDATE = #{cdate,jdbcType=DATE} and date_type=0
	and PORTFOLIO_ID = #{portfolioId,jdbcType=VARCHAR}
	and HODING_TYPE = #{hodingType,jdbcType=VARCHAR}
	and SEC_ACCT_ID = #{secAcctId,jdbcType=VARCHAR}
  and FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
  and CCY = #{ccy,jdbcType=VARCHAR}
